//! `startprofiler` and `stopprofiler` over the daemon's profile server
//! manager, `profiler::ProfileServer`.
//!
//! The daemon used to hand the RPC server the `()` stand-in, so every
//! `startprofiler` answered -8 "unable to start profile server: RPC server
//! seam start is not wired in this build", even for an address dcrd
//! refuses up front.  The rows of `data/profiler_vectors.txt` are what
//! dcrd's own `profileServer.Start` returned for 65 calls, generated by
//! `tools/profilergen` inside dcrd's package main at `382ff4dd`, the
//! parity pin then (`release-v2.1.7` gives the same file, and
//! `profiler.go` is unchanged at `3360ae4d`): each refusal by
//! `net.SplitHostPort`, `validateProfileAddr`, the loopback check and
//! `parseListeners`, and the addresses that pass every check.  Each row is
//! replayed through the manager and through the RPC dispatch, and the
//! reply compared byte for byte: dcrd's text for a refusal, and the
//! deliberate refusal for an address dcrd would listen on.  The refusals a
//! dcrd 2.1.7 node gave dcrctl are pinned too, as are the limited user's
//! refusal and the server dcrd records with no listener for an interface
//! with no address (QUIRKS.md QK-0032).  `review_profiler_daemon.rs`
//! drives the same requests and `--profile` through the daemon binary.

use dcroxide_chaincfg::simnet_params;
use dcroxide_chainhash::Hash;
use dcroxide_dcrjson::RpcId;
use dcroxide_dcrjson::gojson::append_json_string;
use dcroxide_node::IfaceAddrs;
use dcroxide_node::profiler::{InterfaceByName, NOT_PORTED, ProfileServer};
use dcroxide_rpc::dispatch::process_request;
use dcroxide_rpc::helpers::NoInterfaces;
use dcroxide_rpc::server::{Config, RpcBestState, RpcChain, RpcProfilerManager, Server};
use dcroxide_standalone::SubsidyCache;
use dcroxide_testutil::unhex;
use dcroxide_wire::PROTOCOL_VERSION;

const VECTORS: &str = include_str!("data/profiler_vectors.txt");

/// The reply to an address dcrd would listen on.
const NOT_PORTED_REPLY: &str = r#"{"jsonrpc":"1.0","result":null,"error":{"code":-8,"message":"unable to start profile server: the profile server is not part of this port of dcrd"},"id":1}"#;

/// No handler these tests reach reads the chain.
struct NoChain;

impl RpcChain for NoChain {
    fn best_snapshot(&self) -> RpcBestState {
        RpcBestState {
            hash: Hash([0x11; 32]),
            prev_hash: Hash([0x22; 32]),
            height: 1,
            bits: 0x207f_ffff,
            next_stake_diff: 0,
            total_subsidy: 0,
            block_size: 0,
            num_txns: 0,
        }
    }
}

/// An interface lookup that finds no interface.
fn no_interfaces() -> InterfaceByName {
    Box::new(|_| None)
}

/// A server whose profile server manager is `profiler`, every other seam
/// left at its stand-in.
fn server_with(profiler: ProfileServer) -> Server<NoChain> {
    let params = simnet_params();
    Server::new(Config {
        chain: NoChain,
        chain_params: params.clone(),
        subsidy_cache: std::sync::Mutex::new(SubsidyCache::new(params)),
        min_relay_tx_fee: 10000,
        max_protocol_version: PROTOCOL_VERSION,
        sync_mgr: Box::new(()),
        conn_mgr: Box::new(()),
        client_cert_auth: false,
        tx_mempooler: Box::new(()),
        clock: Box::new(()),
        interfaces: Box::new(NoInterfaces),
        rand_u64: Box::new(|| 7),
        tx_indexer: None,
        db: Box::new(()),
        filterer_v2: Box::new(()),
        exists_addresser: None,
        log_manager: Box::new(()),
        fee_estimator: Box::new(()),
        block_templater: None,
        sanity_checker: Box::new(()),
        time_source: Box::new(()),
        proxy: String::new(),
        test_net: false,
        runtime_version: String::new(),
        cpu_miner: Box::new(()),
        mix_pooler: Box::new(()),
        profiler_mgr: Box::new(profiler),
        addr_manager: Box::new(()),
        mining_addrs: Vec::new(),
        user_agent_version: String::new(),
        net_info: Vec::new(),
        services: 0,
        request_shutdown: Box::new(|| {}),
        allow_unsynced_mining: false,
        rpc_user: "admin".to_string(),
        rpc_pass: "adminpass".to_string(),
        rpc_limit_user: "limited".to_string(),
        rpc_limit_pass: "limitedpass".to_string(),
    })
}

/// A JSON string, escaped as Go's `encoding/json` escapes it.
fn json_string(s: &str) -> String {
    let mut out = String::new();
    append_json_string(&mut out, s);
    out
}

/// One request through the dispatch, with dcrctl's version and id.
fn call(server: &Server<NoChain>, method: &str, params: &[&str], is_admin: bool) -> String {
    process_request(server, "1.0", method, params, &RpcId::Int(1), is_admin)
        .expect("a request with an id has a reply")
}

/// The reply dcrd's handler gives when `Start` fails with `text`.
fn start_failure_reply(text: &str) -> String {
    format!(
        r#"{{"jsonrpc":"1.0","result":null,"error":{{"code":-8,"message":{}}},"id":1}}"#,
        json_string(&format!("unable to start profile server: {text}"))
    )
}

/// Every row: the manager refuses with dcrd's text, or with the
/// deliberate refusal where dcrd would bind, and the RPC reply wraps it as
/// dcrd's handler does.
#[test]
fn every_row_replays_through_the_manager_and_the_dispatch() {
    let mut rows = 0usize;
    let mut accepted = 0usize;
    for line in VECTORS.lines() {
        let f: Vec<&str> = line.split('|').collect();
        assert_eq!(f[0], "start", "{line}");
        let allow = match f[1] {
            "0" => false,
            "1" => true,
            other => panic!("allow flag {other} in {line}"),
        };
        let addr = String::from_utf8(unhex(f[2])).expect("a UTF-8 address");
        let want = match f[3] {
            "accept" => NOT_PORTED.to_string(),
            "err" => String::from_utf8(unhex(f[4])).expect("a UTF-8 error"),
            other => panic!("verdict {other} in {line}"),
        };
        if f[3] == "accept" {
            accepted = accepted.saturating_add(1);
        }

        let profiler = ProfileServer::new(no_interfaces());
        assert_eq!(
            profiler.start(&addr, allow),
            Err(want.clone()),
            "start({addr:?}, {allow})"
        );
        assert!(profiler.listeners().is_empty(), "{addr:?}");

        let server = server_with(ProfileServer::new(no_interfaces()));
        let addr_param = json_string(&addr);
        let mut params = vec![addr_param.as_str()];
        if allow {
            params.push("true");
        }
        assert_eq!(
            call(&server, "startprofiler", &params, true),
            start_failure_reply(&want),
            "startprofiler {addr:?} {allow}"
        );
        assert_eq!(
            call(&server, "stopprofiler", &[], true),
            r#"{"jsonrpc":"1.0","result":null,"error":{"code":-26,"message":"profile server is not started"},"id":1}"#
        );
        rows = rows.saturating_add(1);
    }
    assert_eq!((rows, accepted), (65, 18));
}

/// The four refusals a dcrd 2.1.7 node gave dcrctl, byte for byte; for
/// the two addresses it listened on and answered its listeners for, the
/// deliberate refusal.  `stopprofiler` then finds no server, which is
/// dcrd's reply once its server is stopped.
#[test]
fn the_refusals_a_dcrd_2_1_7_node_gave_dcrctl_are_reproduced() {
    let server = server_with(ProfileServer::new(no_interfaces()));
    let request = |method: &str, params: &str| {
        let body = format!(r#"{{"jsonrpc":"1.0","method":"{method}","params":{params},"id":1}}"#);
        String::from_utf8(dcroxide_rpc::http::process_body(&server, &body, true))
            .expect("a UTF-8 reply")
    };
    let refused = [
        (
            r#"["bogus"]"#,
            r#"{"jsonrpc":"1.0","result":null,"error":{"code":-8,"message":"unable to start profile server: address bogus: missing port in address"},"id":1}"#,
        ),
        (
            r#"["127.0.0.1"]"#,
            r#"{"jsonrpc":"1.0","result":null,"error":{"code":-8,"message":"unable to start profile server: address 127.0.0.1: missing port in address"},"id":1}"#,
        ),
        (
            r#"["192.0.2.1:20104"]"#,
            r#"{"jsonrpc":"1.0","result":null,"error":{"code":-8,"message":"unable to start profile server: not permitted to listen on non loopback address \"192.0.2.1:20104\" without setting the flag to allow it"},"id":1}"#,
        ),
        (
            r#"["127.0.0.1:80"]"#,
            r#"{"jsonrpc":"1.0","result":null,"error":{"code":-8,"message":"unable to start profile server: address \"127.0.0.1:80\": port must be between 1024 and 65535"},"id":1}"#,
        ),
    ];
    for (params, reply) in refused {
        assert_eq!(
            request("startprofiler", params).trim_end(),
            reply,
            "{params}"
        );
    }
    for params in [r#"["127.0.0.1:20103"]"#, r#"["20103"]"#] {
        assert_eq!(
            request("startprofiler", params).trim_end(),
            NOT_PORTED_REPLY,
            "{params}"
        );
    }
    assert_eq!(
        request("stopprofiler", "[]").trim_end(),
        r#"{"jsonrpc":"1.0","result":null,"error":{"code":-26,"message":"profile server is not started"},"id":1}"#
    );
}

/// The flag's default is false, explicitly or not, and an explicit null
/// leaves it unset, as dcrd's `jsonrpcdefault` does.
#[test]
fn the_allow_flag_defaults_to_false() {
    let server = server_with(ProfileServer::new(no_interfaces()));
    let refused = start_failure_reply(
        "not permitted to listen on non loopback address \"192.0.2.1:20104\" without \
         setting the flag to allow it",
    );
    for params in [
        &[r#""192.0.2.1:20104""#][..],
        &[r#""192.0.2.1:20104""#, "false"],
        &[r#""192.0.2.1:20104""#, "null"],
    ] {
        assert_eq!(call(&server, "startprofiler", params, true), refused);
    }
    assert_eq!(
        call(
            &server,
            "startprofiler",
            &[r#""192.0.2.1:20104""#, "true"],
            true
        ),
        NOT_PORTED_REPLY
    );
}

/// Neither method is on dcrd's limited user list, so a limited user is
/// refused before the address is read.
#[test]
fn a_limited_user_is_refused_both_methods() {
    let server = server_with(ProfileServer::new(no_interfaces()));
    let refused = r#"{"jsonrpc":"1.0","result":null,"error":{"code":-8,"message":"limited user not authorized for this method"},"id":1}"#;
    assert_eq!(
        call(&server, "startprofiler", &[r#""bogus""#], false),
        refused
    );
    assert_eq!(call(&server, "stopprofiler", &[], false), refused);
}

/// An interface with no address normalizes to no address, so dcrd binds
/// nothing and records a server with no listener: the handler answers its
/// internal error, and so does every later start whatever its address,
/// while `stopprofiler` finds no listener and stops nothing.  Only the
/// daemon's stop at shutdown clears it.  An interface with addresses is
/// checked address by address.
#[test]
fn an_interface_with_no_address_records_a_server_with_no_listener() {
    let profiler = ProfileServer::new(Box::new(|name| match name {
        "eth1" => Some(IfaceAddrs {
            index: 3,
            addrs: Vec::new(),
        }),
        "lo" => Some(IfaceAddrs {
            index: 1,
            addrs: vec![
                "127.0.0.1".parse().expect("IPv4"),
                "::1".parse().expect("IPv6"),
            ],
        }),
        "eth0" => Some(IfaceAddrs {
            index: 2,
            addrs: vec!["fe80::2".parse().expect("IPv6")],
        }),
        _ => None,
    }));
    let server = server_with(profiler.clone());

    assert_eq!(
        call(&server, "startprofiler", &[r#""lo:20103""#], true),
        NOT_PORTED_REPLY
    );
    assert_eq!(
        call(&server, "startprofiler", &[r#""eth0:20103""#], true),
        start_failure_reply(
            "not permitted to listen on non loopback address \"[fe80::2%2]:20103\" without \
             setting the flag to allow it"
        )
    );

    let no_listener = r#"{"jsonrpc":"1.0","result":null,"error":{"code":-32603,"message":"profile server started without active listeners"},"id":1}"#;
    let not_started = r#"{"jsonrpc":"1.0","result":null,"error":{"code":-26,"message":"profile server is not started"},"id":1}"#;
    assert_eq!(
        call(&server, "startprofiler", &[r#""eth1:20103""#], true),
        no_listener
    );
    for params in [
        &[r#""bogus""#][..],
        &[r#""lo:20103""#],
        &[r#""eth0:20103""#, "true"],
    ] {
        assert_eq!(call(&server, "startprofiler", params, true), no_listener);
    }
    assert_eq!(call(&server, "stopprofiler", &[], true), not_started);
    assert_eq!(
        call(&server, "startprofiler", &[r#""bogus""#], true),
        no_listener
    );

    assert_eq!(profiler.stop(), Ok(()));
    assert_eq!(
        call(&server, "startprofiler", &[r#""bogus""#], true),
        start_failure_reply("address bogus: missing port in address")
    );
    assert_eq!(call(&server, "stopprofiler", &[], true), not_started);
}
